import csv, re, datetime
from decimal import Decimal
rows=list(csv.DictReader(open('expenses.csv',newline='')))
def pdate(s):
    s=s.strip()
    for f in ('%Y-%m-%d','%m/%d/%Y','%d %b %Y','%d %B %Y'):
        try: return datetime.datetime.strptime(s,f).date()
        except: pass
    raise Exception(s)
def amt(s):
    return Decimal(re.sub(r'[^0-9.]','',s))
seen=set(); t=Decimal(0); cats={}
for r in rows:
    if r['id'] in seen: continue
    seen.add(r['id'])
    d=pdate(r['date'])
    if (d.year,d.month)!=(2026,10) or r['status'].strip().lower()=='void': continue
    c=r['category'].strip().lower(); a=amt(r['amount'])
    t+=a; cats.setdefault(c,[0,Decimal(0)]); cats[c][0]+=1; cats[c][1]+=a
print('total',t)
for k,v in cats.items(): print(k,v)
PY", "description": "Independently verify totals by category"}

